from typing import List

class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])
        INF = -10**15

        # dp[i][j][k] = max profit at (i,j) having used k neutralizations (k = 0..2)
        dp = [[[INF] * 3 for _ in range(n)] for __ in range(m)]

        # initialise start cell (0,0)
        start = coins[0][0]
        if start >= 0:
            dp[0][0][0] = start
        else:
            dp[0][0][0] = start          # take the loss
            dp[0][0][1] = 0              # neutralize it

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue
                cur = coins[i][j]
                for k in range(3):
                    best = INF

                    # come from top without using a new neutralization
                    if i > 0:
                        prev = dp[i-1][j][k]
                        if prev != INF:
                            best = max(best, prev + cur)

                    # come from left without using a new neutralization
                    if j > 0:
                        prev = dp[i][j-1][k]
                        if prev != INF:
                            best = max(best, prev + cur)

                    # if current cell is a robber and we still have a neutralization left
                    if cur < 0 and k > 0:
                        # come from top having used one less neutralization
                        if i > 0:
                            prev = dp[i-1][j][k-1]
                            if prev != INF:
                                best = max(best, prev)   # neutralized, no change
                        # come from left having used one less neutralization
                        if j > 0:
                            prev = dp[i][j-1][k-1]
                            if prev != INF:
                                best = max(best, prev)

                    dp[i][j][k] = best

        return max(dp[m-1][n-1])
