class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)

        # split pattern into three parts a * b * c
        first = p.find('*')
        second = p.find('*', first + 1)
        a = p[:first]
        b = p[first + 1:second]
        c = p[second + 1:]

        la, lb, lc = len(a), len(b), len(c)

        # all parts empty => empty substring matches
        if la == 0 and lb == 0 and lc == 0:
            return 0

        INF = n + 1

        def kmp_positions(text: str, pat: str):
            """return list of start indices where pat occurs in text (pat non‑empty)"""
            m = len(pat)
            lps = [0] * m
            # build lps
            length = 0
            i = 1
            while i < m:
                if pat[i] == pat[length]:
                    length += 1
                    lps[i] = length
                    i += 1
                else:
                    if length != 0:
                        length = lps[length - 1]
                    else:
                        lps[i] = 0
                        i += 1
            # search
            res = []
            i = j = 0
            while i < len(text):
                if text[i] == pat[j]:
                    i += 1
                    j += 1
                    if j == m:
                        res.append(i - j)
                        j = lps[j - 1]
                else:
                    if j != 0:
                        j = lps[j - 1]
                    else:
                        i += 1
            return res

        # prepare match arrays and next occurrence arrays
        def prepare(part: str):
            if not part:
                return [], [INF] * (n + 1)   # dummy
            matches = kmp_positions(s, part)
            occ = [False] * n
            for pos in matches:
                occ[pos] = True
            nxt = [INF] * (n + 1)
            nxt[n] = INF
            for i in range(n - 1, -1, -1):
                nxt[i] = i if occ[i] else nxt[i + 1]
            return matches, nxt

        matches_a, nxt_a = prepare(a) if la else ([], [])
        matches_b, nxt_b = prepare(b) if lb else ([], [])
        matches_c, nxt_c = prepare(c) if lc else ([], [])

        ans = INF

        # Helper to get minimal length given start index of a (or b when a empty)
        if la > 0:
            for a_start in matches_a:
                a_end = a_start + la

                if lb > 0:
                    b_start = nxt_b[a_end]
                    if b_start == INF:
                        continue
                    b_end = b_start + lb
                else:
                    b_start = a_end
                    b_end = a_end

                if lc > 0:
                    c_start = nxt_c[b_end]
                    if c_start == INF:
                        continue
                    c_end = c_start + lc
                    length = c_end - a_start
                else:
                    length = b_end - a_start

                if length < ans:
                    ans = length
        else:
            # a is empty, start at b_start (or c_start if b also empty)
            if lb > 0:
                for b_start in matches_b:
                    b_end = b_start + lb
                    if lc > 0:
                        c_start = nxt_c[b_end]
                        if c_start == INF:
                            continue
                        c_end = c_start + lc
                        length = c_end - b_start
                    else:
                        length = b_end - b_start
                    if length < ans:
                        ans = length
            else:
                # both a and b empty, only c matters (or all empty already handled)
                if lc > 0:
                    if matches_c:
                        ans = lc   # any occurrence gives length lc
                else:
                    # all parts empty already returned
                    pass

        return -1 if ans == INF else ans
