from typing import List
from collections import defaultdict

class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if k > n:
            return -1

        occ = defaultdict(int)  # number -> count of subarrays containing it

        for i in range(n - k + 1):
            window_set = set(nums[i:i + k])
            for x in window_set:
                occ[x] += 1

        ans = -1
        for x, cnt in occ.items():
            if cnt == 1 and x > ans:
                ans = x
        return ans
