class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        for i in range(n - k + 1):
            # check if all characters in s[i:i+k] are the same
            segment = s[i:i + k]
            if segment.count(segment[0]) != k:
                continue
            c = segment[0]
            # left neighbor condition
            if i > 0 and s[i - 1] == c:
                continue
            # right neighbor condition
            if i + k < n and s[i + k] == c:
                continue
            return True
        return False
