from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # threshold >= 1 by constraints, it does not affect feasibility because we can use at most one outgoing edge per node.
        weights = sorted({w for _, _, w in edges})
        if not weights:
            return -1

        def feasible(limit: int) -> bool:
            rev_adj = [[] for _ in range(n)]
            for a, b, w in edges:
                if w <= limit:
                    rev_adj[b].append(a)   # reversed edge
            q = deque([0])
            seen = [False] * n
            seen[0] = True
            cnt = 1
            while q:
                cur = q.popleft()
                for nei in rev_adj[cur]:
                    if not seen[nei]:
                        seen[nei] = True
                        cnt += 1
                        q.append(nei)
            return cnt == n

        # quick check if impossible even with max weight
        if not feasible(weights[-1]):
            return -1

        lo, hi = 0, len(weights) - 1
        ans = weights[-1]
        while lo <= hi:
            mid = (lo + hi) // 2
            if feasible(weights[mid]):
                ans = weights[mid]
                hi = mid - 1
            else:
                lo = mid + 1
        return ans
