class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)

        # precompute for each d (1..9) the structure info
        info = {}
        for d in range(1, 10):
            # compute sequence of 10^len % d for len >=1
            seen = {}
            seq = []          # seq[idx] = 10^{idx+1} % d
            val = 10 % d
            idx = 1
            while True:
                if val in seen:
                    start = seen[val]          # first occurrence (1‑based)
                    period = idx - start
                    prefix_len = start - 1      # lengths before the cycle
                    break
                seen[val] = idx
                seq.append(val)
                val = (val * 10) % d
                idx += 1

            # pre‑period powers
            pre_pow = [0] + seq[:prefix_len]          # 1‑based, index = length
            # cycle powers for lengths >= prefix_len+1
            cycle_pow = []
            if period:
                # build one full cycle
                for i in range(period):
                    # length = prefix_len + 1 + i
                    cycle_pow.append(seq[prefix_len + i])

            # need tables
            need_pre = {}
            for length in range(1, prefix_len + 1):
                need_pre[length] = {}
                p = pre_pow[length]
                for target in range(d):
                    lst = []
                    for r in range(d):
                        if (r * p) % d == target:
                            lst.append(r)
                    need_pre[length][target] = lst

            need_cycle = {}
            if period:
                for mod in range(period):
                    p = cycle_pow[mod]               # length where (len % period) == mod (with len>0)
                    need_cycle[mod] = {}
                    for target in range(d):
                        lst = []
                        for r in range(d):
                            if (r * p) % d == target:
                                lst.append(r)
                        need_cycle[mod][target] = lst

            info[d] = {
                'd': d,
                'prefix_len': prefix_len,
                'period': period,
                'pre_pow': pre_pow,
                'cycle_pow': cycle_pow,
                'need_pre': need_pre,
                'need_cycle': need_cycle,
            }

            # initialise data structures
            if prefix_len == 0:          # pure periodic case
                cnt = [ [0] * d for _ in range(period) ]
                cnt[1 % period][0] = 1    # the empty prefix (-1) distance =1
                info[d]['cnt'] = cnt
            else:                         # there is a pre‑period (pow becomes 0)
                recent = [dict() for _ in range(prefix_len)]
                recent[0][0] = 1          # distance 1 for the empty prefix
                info[d]['recent'] = recent
                info[d]['old_total'] = 0  # prefixes whose distance > prefix_len

        # current prefix modulo for each d
        cur_mod = {d: 0 for d in range(1, 10)}
        ans = 0

        for ch in s:
            digit = ord(ch) - 48

            # update prefix remainders
            for d in range(1, 10):
                cur_mod[d] = (cur_mod[d] * 10 + digit) % d

            # count substrings ending here where last digit == digit (non‑zero)
            if digit != 0:
                d = digit
                inf = info[d]
                if inf['prefix_len'] == 0:
                    # periodic case
                    period = inf['period']
                    need_cycle = inf['need_cycle']
                    cnt = inf['cnt']
                    target = cur_mod[d]
                    for mod in range(period):
                        lst = need_cycle[mod][target]
                        if not lst:
                            continue
                        arr = cnt[mod]
                        for r in lst:
                            ans += arr[r]
                else:
                    # pre‑period case (pow becomes zero)
                    recent = inf['recent']
                    old_total = inf['old_total']
                    need_pre = inf['need_pre']
                    target = cur_mod[d]

                    # contributions from recent distances (1..prefix_len)
                    for idx, dic in enumerate(recent):
                        length = idx + 1
                        p = inf['pre_pow'][length]
                        if p == 0:
                            if target == 0:
                                ans += sum(dic.values())
                        else:
                            for r in need_pre[length][target]:
                                ans += dic.get(r, 0)

                    # contributions from old_total (pow == 0)
                    if target == 0:
                        ans += old_total

            # ----- update structures for next position -----
            for d in range(1, 10):
                inf = info[d]
                if inf['prefix_len'] == 0:
                    # rotate cnt
                    period = inf['period']
                    cnt = inf['cnt']
                    new_cnt = [ [0] * d for _ in range(period) ]
                    for mod in range(period):
                        new_mod = (mod + 1) % period
                        new_cnt[new_mod] = cnt[mod]
                    # add current prefix with distance 0 (mod 0)
                    new_cnt[0][cur_mod[d]] += 1
                    inf['cnt'] = new_cnt
                else:
                    # shift recent, move last to old_total
                    recent = inf['recent']
                    old_total = inf['old_total']
                    if inf['prefix_len'] > 0:
                        last = recent[-1]
                        old_total += sum(last.values())
                        recent = [dict()] + recent[:-1]
                    # add current prefix (distance will be 1 next step)
                    recent[0][cur_mod[d]] = recent[0].get(cur_mod[d], 0) + 1
                    inf['recent'] = recent
                    inf['old_total'] = old_total

        return ans
