from typing import List

class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total = 0
        for i, val in enumerate(nums):
            left_ok = (i - k < 0) or (val > nums[i - k])
            right_ok = (i + k >= n) or (val > nums[i + k])
            if left_ok and right_ok:
                total += val
        return total
