from typing import List

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + nums[i]

        INF_NEG = -10**15
        dp = [[INF_NEG] * (k + 1) for _ in range(n + 1)]
        dp[0][0] = 0

        for j in range(1, k + 1):
            best = INF_NEG  # max of dp[t][j-1] - prefix[t] for t <= i-m
            for i in range(1, n + 1):
                # update best with start position t = i-m
                if i - m >= 0:
                    t = i - m
                    if dp[t][j - 1] != INF_NEG:
                        best = max(best, dp[t][j - 1] - prefix[t])
                # option 1: skip current element
                dp[i][j] = dp[i - 1][j]
                # option 2: end a subarray at i (length >= m)
                if best != INF_NEG:
                    dp[i][j] = max(dp[i][j], prefix[i] + best)

        return dp[n][k]
