class Solution:
    def findValidPair(self, s: str) -> str:
        # count occurrences of each digit
        cnt = [0] * 10
        for ch in s:
            cnt[int(ch)] += 1

        # scan adjacent pairs
        for i in range(len(s) - 1):
            a, b = s[i], s[i + 1]
            if a == b:
                continue
            if cnt[int(a)] == int(a) and cnt[int(b)] == int(b):
                return a + b
        return ""
