from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]          # clockwise order
        # dp2[d][i][j] : longest alternating length starting at (i,j) assuming this cell must be 2
        # dp0[d][i][j] : same but this cell must be 0
        dp2 = [[[0] * m for _ in range(n)] for _ in range(4)]
        dp0 = [[[0] * m for _ in range(n)] for _ in range(4)]

        # helper to decide iteration order for a direction
        def iter_order(dx, dy):
            if dx == 1:
                rs = range(n - 1, -1, -1)
            else:
                rs = range(n)
            if dy == 1:
                cs = range(m - 1, -1, -1)
            else:
                cs = range(m)
            return rs, cs

        for d, (dx, dy) in enumerate(dirs):
            rs, cs = iter_order(dx, dy)
            for i in rs:
                for j in cs:
                    ni, nj = i + dx, j + dy
                    if grid[i][j] == 2:
                        if 0 <= ni < n and 0 <= nj < m:
                            dp2[d][i][j] = 1 + dp0[d][ni][nj]
                        else:
                            dp2[d][i][j] = 1
                    else:
                        dp2[d][i][j] = 0
                    if grid[i][j] == 0:
                        if 0 <= ni < n and 0 <= nj < m:
                            dp0[d][i][j] = 1 + dp2[d][ni][nj]
                        else:
                            dp0[d][i][j] = 1
                    else:
                        dp0[d][i][j] = 0

        ans = 0

        for i in range(n):
            for j in range(m):
                if grid[i][j] != 1:
                    continue
                ans = max(ans, 1)        # segment consisting of the single 1
                for d, (dx, dy) in enumerate(dirs):
                    # ----- straight segment without turn -----
                    ni, nj = i + dx, j + dy
                    straight_len = 1
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 2:
                        straight_len += dp0[d][ni][nj]
                    ans = max(ans, straight_len)

                    # ----- turn at the starting cell -----
                    nd = (d + 1) % 4
                    tx, ty = i + dirs[nd][0], j + dirs[nd][1]
                    if 0 <= tx < n and 0 <= ty < m and grid[tx][ty] == 2:
                        tail = dp0[nd][tx][ty]   # after a 2 we need 0 next
                        ans = max(ans, 1 + 1 + tail)   # start + first turned cell + tail
                    # ----- turn after moving k steps (k >= 0) -----
                    x, y = i + dx, j + dy
                    steps = 0          # steps taken after the start (k)
                    while 0 <= x < n and 0 <= y < m:
                        expected = 2 if steps % 2 == 0 else 0
                        if grid[x][y] != expected:
                            break
                        # length up to current pivot (inclusive)
                        cur_len = 1 + steps + 1          # start + (steps+1) cells visited
                        # next expected after this pivot
                        next_expected = 0 if grid[x][y] == 2 else 2
                        nd = (d + 1) % 4
                        nx, ny = x + dirs[nd][0], y + dirs[nd][1]
                        tail = 0
                        if 0 <= nx < n and 0 <= ny < m:
                            if next_expected == 2:
                                tail = dp2[nd][nx][ny]
                            else:
                                tail = dp0[nd][nx][ny]
                        ans = max(ans, cur_len + tail)

                        # move further along straight direction
                        x += dx
                        y += dy
                        steps += 1

        return ans
