from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # build order: 0, n-1, 1, n-2, 2, n-3, ...
        order = []
        l, r = 0, n - 1
        while l < r:
            order.append(l)
            order.append(r)
            l += 1
            r -= 1
        # mapping from node to its position in order
        pos_of = [0] * n
        for idx, v in enumerate(order):
            pos_of[v] = idx

        # adjacency list (only needed for earlier neighbors)
        adj = [[] for _ in range(n)]
        for i in range(n):
            if i - 1 >= 0:
                adj[i].append(i - 1)
            if i + 1 < n:
                adj[i].append(i + 1)
            mirror = n - 1 - i
            if mirror != i:
                adj[i].append(mirror)

        INF = 10**18
        # dp maps (prev1_color, prev2_color) -> min cost so far
        # prev1 is color of most recent processed node (pos-1)
        # prev2 is color of node at pos-2 (or -1 if not existent)
        dp = {(-1, -1): 0}

        for pos in range(n):
            v = order[pos]
            new_dp = {}
            for (prev1, prev2), cur_cost in dp.items():
                for c in range(3):
                    ok = True
                    for nb in adj[v]:
                        nb_pos = pos_of[nb]
                        if nb_pos >= pos:
                            continue  # neighbor not processed yet
                        if nb_pos == pos - 1:
                            if c == prev1:
                                ok = False
                                break
                        elif nb_pos == pos - 2:
                            if c == prev2:
                                ok = False
                                break
                    if not ok:
                        continue
                    key = (c, prev1)
                    val = cur_cost + cost[v][c]
                    if val < new_dp.get(key, INF):
                        new_dp[key] = val
            dp = new_dp

        return min(dp.values())
