from collections import Counter

class Solution:
    def maxDifference(self, s: str) -> int:
        freq = Counter(s)
        max_odd = -10**9
        min_even = 10**9
        for cnt in freq.values():
            if cnt % 2 == 1:
                if cnt > max_odd:
                    max_odd = cnt
            else:
                if cnt < min_even:
                    min_even = cnt
        # As per constraints, both will be set
        return max_odd - min_even
