from typing import List

class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        total_k = sum(1 for x in nums if x == k)
        best_gain = 0
        values = set(nums)
        values.discard(k)            # we only need to consider v != k
        for v in values:
            cur = 0
            for x in nums:
                if x == v:
                    cur += 1
                elif x == k:
                    cur -= 1
                # else add 0
                if cur < 0:
                    cur = 0
                if cur > best_gain:
                    best_gain = cur
        return total_k + best_gain
