from typing import List, Dict

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        max_g = max(groups)
        # map group value to list of indices having that value
        groups_by_val: Dict[int, List[int]] = {}
        for idx, g in enumerate(groups):
            groups_by_val.setdefault(g, []).append(idx)

        answer = [-1] * len(groups)
        assigned = 0
        total = len(groups)
        seen_vals = set()

        for j, val in enumerate(elements):
            if val in seen_vals:
                continue
            seen_vals.add(val)

            # iterate over multiples of val up to max_g
            for mult in range(val, max_g + 1, val):
                lst = groups_by_val.get(mult)
                if not lst:
                    continue
                for idx in lst:
                    if answer[idx] == -1:
                        answer[idx] = j
                        assigned += 1
                # clear to avoid revisiting these groups later
                groups_by_val[mult] = []
            if assigned == total:
                break

        return answer
