from typing import List

class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        total_area = 0.0
        mins = float('inf')
        maxs = -float('inf')
        for x, y, l in squares:
            total_area += l * l
            mins = min(mins, y)
            maxs = max(maxs, y + l)
        target = total_area / 2.0

        lo, hi = mins, maxs
        for _ in range(80):  # sufficient for 1e-5 precision
