import heapq

class Solution:
    def maxSum(self, grid: List[List[int]], limits: List[int], k: int) -> int:
        candidates = []
        for row, lim in zip(grid, limits):
            if lim == 0:
                continue
            # take the largest min(lim, len(row)) elements from the row
            top = heapq.nlargest(min(lim, len(row)), row)
            candidates.extend(top)
        if k == 0 or not candidates:
            return 0
        if k >= len(candidates):
            return sum(candidates)
        # sum of k largest elements in candidates
        return sum(heapq.nlargest(k, candidates))
