class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        # fixed characters from 'T' constraints
        fixed = [None] * L
        for i, ch in enumerate(str1):
            if ch == 'T':
                for j in range(m):
                    p = i + j
                    c = str2[j]
                    if fixed[p] is not None and fixed[p] != c:
                        return ""
                    fixed[p] = c

        # intervals for 'F' constraints
        intervals = []                     # list of (start, end)
        start_at = [[] for _ in range(L)]
        end_at = [[] for _ in range(L)]
        for i, ch in enumerate(str1):
            if ch == 'F':
                s = i
                e = i + m - 1
                idx = len(intervals)
                intervals.append((s, e))
                start_at[s].append(idx)
                end_at[e].append(idx)

        total_intervals = len(intervals)
        satisfied = [False] * total_intervals
        active = set()                     # indices of intervals currently covering current position

        result = []
        for p in range(L):
            # add intervals starting now
            for idx in start_at[p]:
                active.add(idx)

            # need to create mismatch at this position for any interval that ends now and is still unsatisfied
            need_mismatch = any(not satisfied[idx] for idx in end_at[p])

            # choose character
            if fixed[p] is not None:
                c = fixed[p]
                if need_mismatch and c == str2[-1]:
                    return ""
            else:
                # smallest possible character respecting need_mismatch
                for cand in map(chr, range(ord('a'), ord('z') + 1)):
                    if need_mismatch and cand == str2[-1]:
                        continue
                    c = cand
                    break
                else:
                    return ""

            result.append(c)

            # update satisfaction for all active intervals
            to_remove = []
            for idx in active:
                if satisfied[idx]:
                    continue
                start, _ = intervals[idx]
                offset = p - start
                if c != str2[offset]:
                    satisfied[idx] = True

            # check intervals ending now
            for idx in end_at[p]:
                if not satisfied[idx]:
                    return ""          # cannot satisfy this F interval
                active.discard(idx)

        return "".join(result)
