from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        n = len(nums)
        max_sum = 12 * n                # maximum absolute alternating sum
        offset = max_sum
        total_bits = 2 * max_sum + 1    # range [-max_sum, max_sum]
        mask_limit = (1 << total_bits) - 1

        # dp[parity][product] -> bitmask of reachable sums (non‑empty subsequences)
        dp = [[0] * (limit + 1) for _ in range(2)]

        # empty subsequence mask (used only as source for first element)
        empty_mask = 1 << offset   # sum = 0

        for a in nums:
            newdp = [dp[0][:], dp[1][:]]   # copy for "skip" option

            # --- start from empty subsequence (length 0, parity 0, product 1) ---
            # parity of empty = 0, product = 1, mask = empty_mask
            if a == 0:
                new_prod = 0
                new_par = 1          # length becomes 1 (odd index)
                new_mask = empty_mask
                newdp[new_par][new_prod] |= new_mask
            else:
                new_prod = a
                if new_prod <= limit:
                    new_par = 1
                    shift = a      # parity 0 -> plus
                    if shift >= 0:
                        new_mask = (empty_mask << shift) & mask_limit
                    else:
                        new_mask = empty_mask >> (-shift)
                    newdp[new_par][new_prod] |= new_mask

            # --- extend existing non‑empty subsequences ---
            for parity in (0, 1):
                for prod in range(limit + 1):
                    mask = dp[parity][prod]
                    if mask == 0:
                        continue
                    new_par = 1 - parity
                    if a == 0:
                        new_prod = 0
                        new_mask = mask
                        newdp[new_par][new_prod] |= new_mask
                    else:
                        new_prod = prod * a
                        if new_prod > limit:
                            continue
                        shift = a if parity == 0 else -a
                        if shift >= 0:
                            new_mask = (mask << shift) & mask_limit
                        else:
                            new_mask = mask >> (-shift)
                        newdp[new_par][new_prod] |= new_mask
            dp = newdp

        target_bit = offset + k
        if target_bit < 0 or target_bit >= total_bits:
            return -1

        for prod in range(limit, -1, -1):
            if (dp[0][prod] >> target_bit) & 1 or (dp[1][prod] >> target_bit) & 1:
                return prod
        return -1
```

