        last = [-1] * 26
        for i, ch in enumerate(s):
            idx = ord(ch) - 97
            if first[idx] == -1:
                first[idx] = i
            last[idx] = i

        intervals = []
        for idx in range(26):
            if first[idx] != -1:
                l, r = first[idx], last[idx]
                # ignore the whole string interval
                if not (l == 0 and r == n - 1):
                    intervals.append((l, r))

