from typing import List

class Solution:
    def minCost(self, nums: List[int]) -> int:
        n = len(nums)

        @lru_cache(None)
        def dp(pos: int, buf: int) -> int:
            # buf == -1 means empty buffer
            if pos == n and buf == -1:
                return 0

            # Build the list of up to first three elements
            cur = []
            if buf != -1:
                cur.append(buf)
            need = 3 - len(cur)
            seg_end = min(n, pos + need)
            cur.extend(nums[pos:seg_end])

            # If we have 0 elements (should not happen except full finished)
            if not cur:
                return 0
            # If 1 or 2 elements remain, finish in one operation
            if len(cur) <= 2:
                return max(cur)

            # len(cur) == 3
            best = float('inf')
            # try removing any two of the first three
            for i in range(3):
                for j in range(i + 1, 3):
                    cost = max(cur[i], cur[j])
                    # remaining element
                    for k in range(3):
                        if k != i and k != j:
                            remaining = cur[k]
                            break
                    # advance position by the number of original elements we consumed
                    new_pos = seg_end
                    best = min(best, cost + dp(new_pos, remaining))
            return best

        return dp(0, -1)
