class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        n = len(original)
        # compute prefix sums of differences
        prefix = [0] * n
        for i in range(1, n):
            prefix[i] = prefix[i-1] + (original[i] - original[i-1])

        INF = 10**18
        L, R = -INF, INF
        for i in range(n):
            u, v = bounds[i]
            li = u - prefix[i]
            ri = v - prefix[i]
            if li > L:
                L = li
            if ri < R:
                R = ri
            if L > R:
                return 0
        return max(0, R - L + 1)
