class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        K = k
        # dp[i][j][c] = max LPS length in s[i..j] using at most c operations
        dp = [[[0] * (K + 1) for _ in range(n)] for __ in range(n)]

        # Base case: single characters
        for i in range(n):
            for c in range(K + 1):
                dp[i][i][c] = 1

        # Helper to compute cyclic distance between two chars
        def cyclic_dist(a: str, b: str) -> int:
            diff = abs(ord(a) - ord(b))
            return diff if diff <= 13 else 26 - diff

        # Build DP for increasing lengths
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                for c in range(K + 1):
                    # Skip either end
                    best = dp[i + 1][j][c]
                    if dp[i][j - 1][c] > best:
                        best = dp[i][j - 1][c]

                    # Try to pair i and j
                    cost = cyclic_dist(s[i], s[j])
                    if c >= cost:
                        inner = 0
                        if i + 1 <= j - 1:
                            inner = dp[i + 1][j - 1][c - cost]
                        candidate = 2 + inner
                        if candidate > best:
                            best = candidate
                    dp[i][j][c] = best

        # Answer: maximum over costs up to K
        return max(dp[0][n - 1])
