from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)
        # build segment tree for max query
        size = 1
        while size < n:
            size <<= 1
        seg = [-1] * (2 * size)
        # fill leaves
        for i in range(n):
            seg[size + i] = baskets[i]
        # build internal nodes
        for i in range(size - 1, 0, -1):
            seg[i] = max(seg[i << 1], seg[(i << 1) | 1])

        def update(pos: int):
            """mark basket at pos as used (set to -1)"""
            idx = size + pos
            seg[idx] = -1
            idx >>= 1
            while idx:
                seg[idx] = max(seg[idx << 1], seg[(idx << 1) | 1])
                idx >>= 1

        def find_first(val: int) -> int:
            """return leftmost index with capacity >= val, or -1 if none"""
            if seg[1] < val:
                return -1
            node = 1
            while node < size:
                left = node << 1
                if seg[left] >= val:
                    node = left
                else:
                    node = left | 1
            idx = node - size
            return idx if idx < n else -1

        unplaced = 0
        for f in fruits:
            idx = find_first(f)
            if idx == -1:
                unplaced += 1
            else:
                update(idx)
        return unplaced
