class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        if n == 0:
            return 0
        max_target = max(nums)
        mask = (1 << (max_target + 1)) - 1  # keep bits only up to max_target
        # dp[i] is a bitmask of achievable sums for index i
        dp = [1] * n  # only sum 0 is achievable initially

        for idx, (l, r, val) in enumerate(queries):
            shift = val
            for i in range(l, r + 1):
                dp[i] = (dp[i] | (dp[i] << shift)) & mask
            # check if all positions can reach their required value
            ok = True
            for i in range(n):
                if not (dp[i] >> nums[i]) & 1:
                    ok = False
                    break
            if ok:
                return idx + 1  # k is 1‑based count of queries processed
        return -1
