from collections import Counter

class Solution:
    def totalNumbers(self, digits: List[int]) -> int:
        cnt = Counter(digits)
        results = set()
        def backtrack(path, counter):
            if len(path) == 3:
                if path[0] != 0 and path[-1] % 2 == 0:
                    num = path[0] * 100 + path[1] * 10 + path[2]
                    results.add(num)
                return
            for d in list(counter.keys()):
                if counter[d] > 0:
                    counter[d] -= 1
                    path.append(d)
                    backtrack(path, counter)
                    path.pop()
                    counter[d] += 1
        backtrack([], cnt)
        return len(results)
