class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        n, m = len(skill), len(mana)
        # pref for previous column (j-1)
        prev_pref = [0] * n
        start_prev = 0  # S_{j-1}
        cur_pref = None

        for j in range(m):
            cur_pref = [0] * n
            # build prefix sums of processing times for this potion (column j)
            for i in range(n):
                proc = skill[i] * mana[j]
                if i == 0:
                    cur_pref[i] = proc
                else:
                    cur_pref[i] = cur_pref[i - 1] + proc

            if j == 0:
                start_curr = 0
            else:
                # compute minimal start time S_j satisfying zero‑wait constraints
                need = start_prev
                for i in range(n):
                    left = prev_pref[i]                     # pref[i][j-1]
                    right = cur_pref[i - 1] if i > 0 else 0 # pref[i-1][j]
                    val = start_prev + left - right
                    if val > need:
                        need = val
                start_curr = need

            # prepare for next iteration
            start_prev = start_curr
            prev_pref = cur_pref

        # makespan = start of last potion + its total processing time on all wizards
        return start_prev + cur_pref[-1]
