import sys

class BIT:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 2)          # 1-indexed internally

    def _add(self, idx, val):
        i = idx + 1
        n = self.n + 1
        while i <= n:
            self.bit[i] += val
            i += i & -i

    def range_add(self, l, r, val):
        if l > r:
            return
        self._add(l, val)
        self._add(r + 1, -val)

    def point_query(self, idx):
        i = idx + 1
        s = 0
        while i:
            s += self.bit[i]
            i -= i & -i
        return s


def solve() -> None:
    data = sys.stdin.read().split()
    it = iter(data)
    N = int(next(it))
    intervals = [(int(next(it)), int(next(it))) for _ in range(N)]
    Q = int(next(it))
    queries = [int(next(it)) for _ in range(Q)]

    MAX_X = 500000  # maximum initial rating given in constraints
    bit = BIT(MAX_X + 2)  # a little extra space

    # helper binary searches
    def first_ge(target: int) -> int:
        lo, hi = 0, MAX_X + 1  # hi is exclusive sentinel
        while lo < hi:
            mid = (lo + hi) // 2
            if mid + bit.point_query(mid) >= target:
                hi = mid
            else:
                lo = mid + 1
        return lo

    def first_gt(target: int) -> int:
        lo, hi = 0, MAX_X + 1
        while lo < hi:
            mid = (lo + hi) // 2
            if mid + bit.point_query(mid) > target:
                hi = mid
            else:
                lo = mid + 1
        return lo

    for L, R in intervals:
        left = first_ge(L)
        right = first_gt(R) - 1
        if left <= right and left <= MAX_X:
            if right > MAX_X:
                right = MAX_X
            bit.range_add(left, right, 1)

    out_lines = []
    for x in queries:
        out_lines.append(str(x + bit.point_query(x)))
    sys.stdout.write("\n".join(out_lines))


if __name__ == "__main__":
    solve()
