import sys

def solve() -> None:
    sys.setrecursionlimit(1000000)
    N, P = map(int, sys.stdin.readline().split())
    a = N // 2          # size of even set (contains vertex 1)
    b = N // 2          # size of odd set

    max_edges = N * (N - 1) // 2
    # precompute binomials up to max_edges
    fact = [1] * (max_edges + 1)
    for i in range(1, max_edges + 1):
        fact[i] = fact[i - 1] * i % P
    inv_fact = [1] * (max_edges + 1)
    inv_fact[max_edges] = pow(fact[max_edges], P - 2, P)
    for i in range(max_edges, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % P

    def C(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * inv_fact[k] % P * inv_fact[n - k] % P

    # store g_total[a][b] = list of counts for each edge count m
    g_total = {}
    # precompute for all a (1..Amax) and b (0..Bmax)
    for aa in range(1, a + 1):
        for bb in range(0, b + 1):
            max_allowed = aa * bb + (bb * (bb - 1) // 2)
            arr = [0] * (max_allowed + 1)
            # inclusion‑exclusion over vertices that have no cross edge
            for i in range(0, aa + 1):
                comb_i = C(aa, i)
                for j in range(0, bb + 1):
                    sign = -1 if ((i + j) & 1) else 1
                    ways_choose = comb_i * C(bb, j) % P
                    cross = (aa - i) * (bb - j)
                    internal = (bb - j) * (bb - j - 1) // 2
                    # convolution of choosing k cross edges and l internal edges
                    for k in range(0, cross + 1):
                        ck = C(cross, k)
                        max_l = internal
                        for l in range(0, max_l + 1):
                            m = k + l
                            if m > max_allowed:
                                break
                            arr[m] = (arr[m] + sign * ways_choose * ck % P * C(internal, l)) % P
            # clean negative mods
            for idx in range(len(arr)):
                arr[idx] %= P
            g_total[(aa, bb)] = arr

    # DP for connected graphs f[a][b][m]
    f = {}
    for aa in range(1, a + 1):
        for bb in range(0, b + 1):
            max_allowed = aa * bb + (bb * (bb - 1) // 2)
            ft = [0] * (max_allowed + 1)
            gt = g_total[(aa, bb)]
            for m in range(0, max_allowed + 1):
                total = gt[m]
                sub = 0
                # split off the component containing vertex 1
                for a1 in range(1, aa + 1):
                    for b1 in range(0, bb + 1):
                        if a1 == aa and b1 == bb:
                            continue
                        chooseA = C(aa - 1, a1 - 1)
                        chooseB = C(bb, b1)
                        maxe1 = a1 * b1 + (b1 * (b1 - 1) // 2)
                        for k in range(0, min(m, maxe1) + 1):
                            val = f.get((a1, b1))
                            if val is None:
                                continue
                            cnt = val[k]
                            if cnt == 0:
                                continue
                            rest_m = m - k
                            rest_a = aa - a1
                            rest_b = bb - b1
                            if rest_a == 0 and rest_b == 0:
                                continue
                            gt_rest = g_total.get((rest_a, rest_b))
                            if gt_rest is None or rest_m >= len(gt_rest):
                                continue
                            ways_rest = gt_rest[rest_m]
                            sub = (sub + chooseA * chooseB % P * cnt % P * ways_rest) % P
                ft[m] = (total - sub) % P
            f[(aa, bb)] = ft

    # final answer
    choose_even_set = C(N - 1, a - 1)
    max_allowed_total = a * b + (b * (b - 1) // 2)
    res = []
    for M in range(N - 1, N * (N - 1) // 2 + 1):
        if M > max_allowed_total:
            res.append('0')
        else:
            val = f[(a, b)][M] if M < len(f[(a, b)]) else 0
            ans = choose_even_set * val % P
            res.append(str(ans))
    print(' '.join(res))

if __name__ == "__main__":
    solve()
