import sys

def solve() -> None:
    sys.setrecursionlimit(1 << 25)
    N, P = map(int, sys.stdin.readline().split())
    E = N * (N - 1) // 2
    max_deg = E

    # precompute binomials modulo P
    C = [[0] * (E + 1) for _ in range(E + 1)]
    for i in range(E + 1):
        C[i][0] = C[i][i] = 1 % P
        for j in range(1, i):
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % P

    # convolution limited to max_deg
    def conv(a, b):
        la, lb = len(a), len(b)
        res = [0] * (min(la + lb - 2, max_deg) + 1)
        for i in range(la):
            ai = a[i]
            if ai == 0:
                continue
            lim = min(lb, max_deg - i + 1)
            for j in range(lim):
                res[i + j] = (res[i + j] + ai * b[j]) % P
        return res

    # precompute factor polynomial for (prev, nxt) where prev = size of previous layer,
    # nxt = size of current layer
    factor = [[None] * (N + 1) for _ in range(N + 1)]
    for prev in range(N + 1):
        for nxt in range(N + 1):
            if nxt == 0:
                factor[prev][nxt] = [1]  # empty layer contributes nothing
                continue
            if prev == 0:
                factor[prev][nxt] = [0]  # impossible, will be ignored
                continue
            # (1+x)^{C(nxt,2)}
            intra_deg = nxt * (nxt - 1) // 2
            poly_intra = [C[intra_deg][k] for k in range(intra_deg + 1)]

            # base = (1+x)^{prev} - 1  (coeff for k>=1)
            base = [0] * (prev + 1)
            for k in range(1, prev + 1):
                base[k] = C[prev][k]

            # (base)^{nxt}
            poly_cross = [1]
            exp = nxt
            cur = base[:]
            while exp:
                if exp & 1:
                    poly_cross = conv(poly_cross, cur)
                exp >>= 1
                if exp:
                    cur = conv(cur, cur)

            # total factor
            factor[prev][nxt] = conv(poly_intra, poly_cross)

    # DP: state -> polynomial
    # key: (even_used, odd_used, prev_size, next_parity)  next_parity: 0 even layer, 1 odd layer
    from collections import defaultdict
    dp = defaultdict(list)
    # start with layer 0 (size 1, even), next layer will be odd
    dp[(1, 0, 1, 1)] = [1]  # polynomial with 0 edges counted so far

    ans = [0] * (max_deg + 1)

    while dp:
        ndp = defaultdict(list)
        for (even, odd, prev, parity), poly in dp.items():
            remaining = N - (even + odd)
            if remaining == 0:
                # finished allocation, add to answer
                for i, v in enumerate(poly):
                    ans[i] = (ans[i] + v) % P
                continue
            if prev == 0:
                continue  # cannot extend further
            # choose size for next layer (must be >=1)
            for sz in range(1, remaining + 1):
                if parity == 0:
                    neven, nodd = even + sz, odd
                else:
                    neven, nodd = even, odd + sz
                nf = factor[prev][sz]
                if nf[0] == 0 and len(nf) == 1:
                    continue  # invalid transition
                newpoly = conv(poly, nf)
                key = (neven, nodd, sz, 1 - parity)
                if not ndp[key]:
                    ndp[key] = newpoly
                else:
                    # add coefficients
                    cur = ndp[key]
                    if len(cur) < len(newpoly):
                        cur.extend([0] * (len(newpoly) - len(cur)))
                    for i in range(len(newpoly)):
                        cur[i] = (cur[i] + newpoly[i]) % P
        dp = ndp

    # output answers for M = N-1 .. E
    out = [str(ans[m] % P) for m in range(N - 1, E + 1)]
    print(' '.join(out))

if __name__ == "__main__":
    solve()
