import sys

class BIT:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, idx, val):
        while idx <= self.n:
            self.bit[idx] += val
            idx += idx & -idx

    def prefix_sum(self, idx):
        s = 0
        while idx:
            s += self.bit[idx]
            idx -= idx & -idx
        return s

    # find smallest index such that prefix sum >= k (k >= 1)
    def kth(self, k):
        idx = 0
        bitmask = 1 << (self.n.bit_length() - 1)
        while bitmask:
            nxt = idx + bitmask
            if nxt <= self.n and self.bit[nxt] < k:
                k -= self.bit[nxt]
                idx = nxt
            bitmask >>= 1
        return idx + 1

def solve() -> None:
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    P = [0] * (n + 1)
    for i in range(1, n + 1):
        P[i] = int(next(it))

    bit = BIT(n)
    for i in range(1, n + 1):
        bit.add(i, 1)          # all positions are initially empty

    ans = [0] * (n + 1)
    for i in range(n, 0, -1):
        pos = bit.kth(P[i])   # find P_i-th empty slot
        ans[pos] = i
        bit.add(pos, -1)      # occupy this slot

    sys.stdout.write(' '.join(map(str, ans[1:])))

if __name__ == "__main__":
    solve()
