import sys
from collections import defaultdict

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N = int(data[0])
    P = int(data[1])

    max_edges = N * (N - 1) // 2
    size = max_edges + 1

    # binomial coefficients modulo P up to max_edges
    comb = [[0] * (max_edges + 1) for _ in range(max_edges + 1)]
    for i in range(max_edges + 1):
        comb[i][0] = comb[i][i] = 1 % P
        for j in range(1, i):
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % P

    # pre‑compute coeff_i = C(cur,i) * (-1)^{cur-i}  (mod P) for cur = 1..N-1
    coeffs = [[] for _ in range(N)]          # coeffs[cur][i]
    for cur in range(1, N):
        lst = [0] * (cur + 1)
        for i in range(cur + 1):
            sign = 1 if ((cur - i) % 2 == 0) else P - 1
            lst[i] = comb[cur][i] * sign % P
        coeffs[cur] = lst

    target_even = N // 2 - 1          # vertices at even distance besides the root

    # dp[used] : dict {(even_sum, prev_size, parity) : polynomial list}
    # parity: 0 -> next level will be odd depth, 1 -> next level even depth
    dp = [defaultdict(lambda: None) for _ in range(N)]
    init_poly = [0] * size
    init_poly[0] = 1
    dp[0][(0, 1, 0)] = init_poly

    for used in range(N - 1):          # total vertices added so far (excluding root)
        cur_dict = dp[used]
        if not cur_dict:
            continue
        for (even_sum, prev_sz, parity), poly in cur_dict.items():
            if poly is None:
                continue
            max_cur = N - 1 - used
            for cur_sz in range(1, max_cur + 1):
                new_even = even_sum + (cur_sz if parity == 1 else 0)
                if new_even > target_even:
                    continue
                new_used = used + cur_sz
                new_parity = 1 - parity
                internal = cur_sz * (cur_sz - 1) // 2
                coeff_list = coeffs[cur_sz]

                new_poly = [0] * size
                for i in range(cur_sz + 1):
                    w = coeff_list[i]
                    if w == 0:
                        continue
                    delta = internal + prev_sz * i
                    if delta > max_edges:
                        continue
                    limit = max_edges - delta
                    for e in range(limit + 1):
                        val = poly[e]
                        if val:
                            new_poly[e + delta] = (new_poly[e + delta] + val * w) % P

                key = (new_even, cur_sz, new_parity)
                existing = dp[new_used].get(key)
                if existing is None:
                    dp[new_used][key] = new_poly
                else:
                    for idx in range(size):
                        existing[idx] = (existing[idx] + new_poly[idx]) % P

    # collect answers for used = N-1
    ans = [0] * size
    final_dict = dp[N - 1]
    for (even_sum, _, _), poly in final_dict.items():
        if even_sum == target_even:
            for m in range(N - 1, size):
                ans[m] = (ans[m] + poly[m]) % P

    out = ' '.join(str(ans[m]) for m in range(N - 1, max_edges + 1))
    print(out)


if __name__ == "__main__":
    solve()
```

This program follows the combinatorial decomposition of graphs by distance levels, uses dynamic programming over the number of vertices placed, the count of even‑distance vertices, the size of the last level, and the parity of the next level.  Transitions add a new level by iterating over possible numbers of edges to the previous level, updating edge‑count distributions without full polynomial convolutions.  The result for each edge count \(M\) is printed modulo the given prime \(P\).

