from math import isqrt

def integer_cuberoot_floor(n: int) -> int:
    # floor of n ** (1/3)
    x = int(round(n ** (1.0 / 3)))
    while (x + 1) ** 3 <= n:
        x += 1
    while x ** 3 > n:
        x -= 1
    return x

def solve() -> None:
    data = sys.stdin.read().strip()
    if not data:
        return
    N = int(data)
    max_d = integer_cuberoot_floor(N) + 2  # safety margin
    for d in range(1, max_d + 1):
        if N % d != 0:
            continue
        M = N // d
        D = 12 * M - 3 * d * d
        if D < 0:
            continue
        s = isqrt(D)
        if s * s != D:
            continue
        num = -3 * d + s
        if num <= 0 or num % 6 != 0:
            continue
        y = num // 6
        if y <= 0:
            continue
        x = y + d
        # final verification (optional but safe)
        if x**3 - y**3 == N:
            print(f"{x} {y}")
            return
    print("-1")

