import sys
sys.setrecursionlimit(1 << 25)

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    K = int(next(it))
    total = N * K
    adj = [[] for _ in range(total)]
    for _ in range(total - 1):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        adj[u].append(v)
        adj[v].append(u)

    if K == 1:
        print("Yes")
        return

    parent = [-1] * total
    order = []
    stack = [0]
    parent[0] = -2
    while stack:
        v = stack.pop()
        order.append(v)
        for to in adj[v]:
            if to == parent[v]:
                continue
            parent[to] = v
            stack.append(to)

    rem = [0] * total          # 0 = no open segment, >0 = length of open segment ending at this node
    possible = True

    for v in reversed(order):
        child_rems = []
        for to in adj[v]:
            if to == parent[v]:
                continue
            r = rem[to]
            if r == -1:
                possible = False
                break
            if r > 0:
                child_rems.append(r)
        if not possible:
            break

        # Pair child remainders to form closed paths of length K
        leftover_len = 0
        if child_rems:
            cnt = {}
            for r in child_rems:
                cnt[r] = cnt.get(r, 0) + 1

            for x in list(cnt.keys()):
                y = K - 1 - x
                if y not in cnt:
                    continue
                if x > y:
                    continue
                if y < 1:   # child remainders are >=1
                    continue
                if x == y:
                    pairs = cnt[x] // 2
                    cnt[x] -= pairs * 2
                else:
                    pairs = min(cnt[x], cnt[y])
                    cnt[x] -= pairs
                    cnt[y] -= pairs

            leftover = [k for k, v in cnt.items() if v > 0]
            if len(leftover) > 1:
                possible = False
                break
            leftover_len = leftover[0] if leftover else 0

        new_len = leftover_len + 1  # add current vertex
        if new_len == K:
            rem[v] = 0
        elif new_len < K:
            rem[v] = new_len
        else:
