import sys

def mat_mul(A, B, mod):
    n = len(A)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        Ai = A[i]
        Ri = res[i]
        for k in range(n):
            aik = Ai[k]
            if aik == 0:
                continue
            Bk = B[k]
            for j in range(n):
                Ri[j] = (Ri[j] + aik * Bk[j]) % mod
    return res

def mat_pow(mat, power, mod):
    n = len(mat)
    # identity matrix
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1 % mod
    base = mat
    while power:
        if power & 1:
            result = mat_mul(result, base, mod)
        base = mat_mul(base, base, mod)
        power >>= 1
    return result

def solve() -> None:
