import sys

def mat_mul(A, B, mod):
    n = len(A)
    C = [[0]*n for _ in range(n)]
    for i in range(n):
        Ai = A[i]
        Ci = C[i]
        for k in range(n):
            aik = Ai[k]
            if aik:
                Bk = B[k]
                mul = aik
                for j in range(n):
                    Ci[j] = (Ci[j] + mul * Bk[j]) % mod
    return C

def mat_pow(M, e, mod):
    n = len(M)
    # identity
    R = [[0]*n for _ in range(n)]
    for i in range(n):
        R[i][i] = 1 % mod
    while e:
        if e & 1:
            R = mat_mul(R, M, mod)
        M = mat_mul(M, M, mod)
        e >>= 1
    return R

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    p = int(next(it))
    A = [[int(next(it)) % p for _ in range(N)] for _ in range(N)]

    K = sum(1 for i in range(N) for j in range(N) if A[i][j] == 0)
    sign = 1 if K % 2 == 0 else (p - 1)  # (-1)^K mod p

    if p == 2:
        val = N % 2
        out = [[val]*N for _ in range(N)]
        for row in out:
            print(' '.join(map(str, row)))
        return

    # compute A^p (or A^3 when p==3)
    Ap = mat_pow(A, p, p)

    # start from Ap
    res = [row[:] for row in Ap]

    # zero diagonal contributions (present for all odd p)
    for i in range(N):
        if A[i][i] == 0:
            for j in range(N):
                res[i][j] = (res[i][j] + A[i][j]) % p
            if p == 3:  # also column contribution only for p==3
                for k in range(N):
                    res[k][i] = (res[k][i] + A[k][i]) % p

    # off‑diagonal zero contributions only when p==3
    if p == 3:
        for u in range(N):
            for v in range(N):
                if u != v and A[u][v] == 0 and A[v][u] != 0:
                    res[u][v] = (res[u][v] + A[v][u]) % p

    # apply overall sign
    if sign != 1:
        for i in range(N):
            for j in range(N):
                res[i][j] = (res[i][j] * sign) % p

    for row in res:
        print(' '.join(map(str, row)))

if __name__ == "__main__":
    solve()
```

This program follows the derived formula:
- For \(p=2\) the answer is a constant matrix \(N \bmod 2\).
- For odd \(p\) compute \(A^p\) modulo \(p\).
- Add contributions from zero diagonal entries (row additions for all odd \(p\), plus column additions when \(p=3\)).
- When \(p=3\) also add contributions from zero off‑diagonal positions whose reverse entry is non‑zero.
- Finally multiply by \((-1)^{K}\) (handled via `sign`).

