    res = []
    for p in small_primes:
        if p * p > x:
            break
        if x % p == 0:
            res.append(p)
            while x % p == 0:
                x //= p
        if x == 1:
            break
    if x > 1:
        res.append(x)
    return res

# ---------- primitive root ----------
def primitive_root(p: int, factors):
    # p is prime, factors = list of distinct prime factors of p-1
    for g in range(2, p):
        for q in factors:
            if pow(g, (p - 1) // q, p) == 1:
                break
        else:
            return g
    return 2  # fallback (should never happen for prime p)

