        for _ in range(s - 1):
            x = (x * x) % n
            if x == n - 1:
                break
        else:
            return False
    return True

# ---------- Pollard Rho ----------
def _mulmod(a, b, mod):
    return (a * b) % mod

def _rho(n):
    if n % 2 == 0:
        return 2
    while True:
        c = random.randrange(1, n)
        f = lambda x: (_mulmod(x, x, n) + c) % n
        x, y, d = 2, 2, 1
        while d == 1:
            x = f(x)
            y = f(f(y))
            d = math.gcd(abs(x - y), n)
        if d != n:
            return d

def factor(n):
    """return list of prime factors (with multiplicities)"""
    if n == 1:
        return []
    if is_prime(n):
        return [n]
    d = _rho(n)
    return factor(d) + factor(n // d)

