import sys

MOD = 998244353

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    A = [int(next(it)) for _ in range(N - 1)]

    maxA = 1000
    spf = list(range(maxA + 1))
    for i in range(2, int(maxA ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, maxA + 1, i):
                if spf[j] == j:
                    spf[j] = i

    prime_to_dlist = {}
    for idx, val in enumerate(A):
        x = val
        while x > 1:
            p = spf[x]
            cnt = 0
            while x % p == 0:
                x //= p
                cnt += 1
            if p not in prime_to_dlist:
                prime_to_dlist[p] = [0] * (N - 1)
            prime_to_dlist[p][idx] = cnt

    ans = 1
    for p, dlist in prime_to_dlist.items():
        total = sum(dlist)
        if total == 0:
            continue
        maxE = total
        powp = [1] * (maxE + 1)
        for e in range(1, maxE + 1):
            powp[e] = powp[e - 1] * p % MOD

        dp0 = [0] * (maxE + 1)   # zero not visited yet
        dp1 = [0] * (maxE + 1)   # zero already visited
        dp1[0] = 1
        for e in range(1, maxE + 1):
            dp0[e] = powp[e]

        for d in dlist:
            new0 = [0] * (maxE + 1)
            new1 = [0] * (maxE + 1)
            if d == 0:
                for e in range(maxE + 1):
                    w0 = dp0[e]
                    if w0:
                        val = w0 * powp[e] % MOD
                        new0[e] = (new0[e] + val) % MOD
                    w1 = dp1[e]
                    if w1:
                        val = w1 * powp[e] % MOD
                        new1[e] = (new1[e] + val) % MOD
            else:
                for e in range(maxE + 1):
                    w0 = dp0[e]
                    w1 = dp1[e]
                    if w0:
                        e2 = e + d
                        if e2 <= maxE:
                            val = w0 * powp[e2] % MOD
                            if e2 == 0:
                                new1[e2] = (new1[e2] + val) % MOD
                            else:
                                new0[e2] = (new0[e2] + val) % MOD
                        if e >= d:
                            e2 = e - d
                            val = w0 * powp[e2] % MOD
                            if e2 == 0:
                                new1[e2] = (new1[e2] + val) % MOD
                            else:
                                new0[e2] = (new0[e2] + val) % MOD
                    if w1:
                        e2 = e + d
                        if e2 <= maxE:
                            val = w1 * powp[e2] % MOD
                            new1[e2] = (new1[e2] + val) % MOD
                        if e >= d:
                            e2 = e - d
                            val = w1 * powp[e2] % MOD
                            new1[e2] = (new1[e2] + val) % MOD
            dp0, dp1 = new0, new1

        S = sum(dp1) % MOD
        ans = ans * S % MOD

    print(ans)

