import sys
from collections import Counter

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    A = [int(next(it)) for _ in range(N)]
    B = [int(next(it)) for _ in range(N)]

    # counts of fixed values
    cntA = Counter()
    cntB = Counter()
    a_flex = b_flex = 0
    max_fixed = 0  # lower bound for S

    for x in A:
        if x == -1:
            a_flex += 1
        else:
            cntA[x] += 1
            if x > max_fixed:
                max_fixed = x
    for x in B:
        if x == -1:
            b_flex += 1
        else:
            cntB[x] += 1
            if x > max_fixed:
                max_fixed = x

    total_fixed_A = sum(cntA.values())
    total_fixed_B = sum(cntB.values())

    # minimum number of fixed-fixed matches required
    needed = max(total_fixed_A - b_flex, total_fixed_B - a_flex)
    if needed <= 0:
        print("Yes")
        return

    # Build possible match counts for each S = a + b where a,b are fixed values
    match = Counter()
    for a_val, ca in cntA.items():
        for b_val, cb in cntB.items():
            S = a_val + b_val
            match[S] += min(ca, cb)

    # also consider S = max_fixed (if no sum gives enough matches)
    # ensure we check S >= max_fixed
    candidates = list(match.keys())
    if max_fixed not in match:
        candidates.append(max_fixed)

    for S in candidates:
        if S < max_fixed:
            continue
        if match.get(S, 0) >= needed:
            print("Yes")
            return
    print("No")

if __name__ == "__main__":
