import sys
from collections import Counter

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    A = [int(next(it)) for _ in range(N)]
    B = [int(next(it)) for _ in range(N)]

    cntA = Counter()
    cntB = Counter()
    unknown_A = unknown_B = 0
    maxA = maxB = -1

    for a in A:
        if a == -1:
            unknown_A += 1
        else:
            cntA[a] += 1
            if a > maxA:
                maxA = a
    for b in B:
        if b == -1:
            unknown_B += 1
        else:
            cntB[b] += 1
            if b > maxB:
                maxB = b

    total_known_A = sum(cntA.values())
    need = total_known_A - unknown_B   # how many known A must be matched with known B

    # If need <= 0, we can satisfy using unknown B slots.
    if need <= 0:
        print("Yes")
        return

    # If there is no known B at all, we cannot match any known A.
    if not cntB:
        print("No")
        return

    # Lower bound for C
    LB = max(maxA if maxA != -1 else 0, maxB if maxB != -1 else 0)

    # Compute matches for each possible sum C = a + b
    matches = {}
    for a, ca in cntA.items():
        for b, cb in cntB.items():
            s = a + b
            # each value a can be matched with value b up to min(ca, cb) times
            matches[s] = matches.get(s, 0) + min(ca, cb)

    for s, m in matches.items():
        if s >= LB and m >= need:
            print("Yes")
            return

    print("No")

if __name__ == "__main__":
    solve()
